bool isOwner = false;
for (uint256 i = 0; i < _owners.length; i++) {
if (_owners[i] == _msgSender()) {
isOwner = true;
break;
}
}
if (!isOwner) {
revert OwnableUnauthorizedAccount(_msgSender());
}
}

